python3 -c "
import json
d=json.load(open('/tmp/object_info.json'))
# find nodes whose input names/values suggest file paths, urls, commands, code
import re
suspicious=[]
for name,node in d.items():
    inp=node.get('input',{})
    def walk(o):
        if isinstance(o,dict):
            for k,v in o.items():
                if isinstance(v,(dict,list)): walk(v)
                elif isinstance(v,str) and re.search(r'(path|url|file|command|cmd|script|python|code|dir|folder|shell|exec|env|key|token|endpoint|host)', v, re.I):
                    suspicious.append((name,k,v))
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(inp)
seen=set()
for name,k,v in suspicious:
    key=(name,k)
    if key in seen: continue
    seen.add(key)
    print(f'{name} :: {k} = {v}')
" | head -120

