args.command:
python3 -c "
import json
d=json.load(open('/tmp/object_info.json'))
pat=['code','command','cmd','python','exec','shell','url','webhook','base_url','file_path','path','endpoint','host','script','env','key','token','dir','folder','filename','command_line','args','bash','sh','curl','wget','os','system','eval']
import re
rx=re.compile('('+'|'.join(pat)+')', re.I)
hits=[]
for name,node in d.items():
    inp=node.get('input',{})
    def walk(o,path):
        if isinstance(o,dict):
            for k,v in o.items():
                walk(v, path+'.'+k)
        elif isinstance(o,list):
            for i,v in enumerate(o):
                walk(v, path+f'[{i}]')
        elif isinstance(o,str):
            pass
    # simpler: collect all keys
    keys=set()
    def collect(o):
        if isinstance(o,dict):
            for k,v in o.items():
                keys.add(k); collect(v)
        elif isinstance(o,list):
            for v in o: collect(v)
    collect(inp)
    for k in keys:
        if rx.search(k):
            hits.append((name,k))
for name,k in sorted(set(hits)):
    print(f'{name} :: {k}')
" | sort -u
